import{_ as o,a}from"./chunks/ptz-2.CeZdEwDh.js";import{_ as i,o as r,c as n,a5 as l,j as e}from"./chunks/framework.CcrBcQWS.js";const y=JSON.parse('{"title":"PTZ GUI","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/ptz-gui.md","filePath":"manual/gui/ptz-gui.md","lastUpdated":1787021357000}'),c={name:"manual/gui/ptz-gui.md"};function s(d,t,m,h,p,u){return r(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="ptz-gui" tabindex="-1">PTZ GUI <a class="header-anchor" href="#ptz-gui" aria-label="Permalink to &quot;PTZ GUI&quot;">​</a></h1><p>If a PTZ camera (optional) is installed, you can control the camera direction (Pan/Tilt), zoom, and video mode (Thermal/Color) from RBQGUI.</p><h2 id="_1-screen-entry" tabindex="-1">1) Screen entry <a class="header-anchor" href="#_1-screen-entry" aria-label="Permalink to &quot;1) Screen entry&quot;">​</a></h2><ol><li>Run RBQGUI and connect to the robot.</li><li>Move to the camera screen, then open the PTZ control screen.</li><li>When the PTZ is connected normally, you can use the control area at the bottom.</li></ol><figure style="margin-top:1rem;text-align:center;"><img src="'+o+'" alt="PTZ GUI main screen" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">PTZ GUI main screen</figcaption></figure><h2 id="_2-basic-operation-pan-tilt" tabindex="-1">2) Basic operation (Pan/Tilt) <a class="header-anchor" href="#_2-basic-operation-pan-tilt" aria-label="Permalink to &quot;2) Basic operation (Pan/Tilt)&quot;">​</a></h2><ul><li>Drag the PTZ control area (virtual joystick) on the screen to move the camera left/right (Pan) and up/down (Tilt).</li><li>When you release your hand, input stops. If needed, drag again for fine adjustments.</li><li>For more accurate positioning, move slowly using smaller inputs instead of fast movements.</li></ul><h2 id="_3-zoom-control" tabindex="-1">3) Zoom control <a class="header-anchor" href="#_3-zoom-control" aria-label="Permalink to &quot;3) Zoom control&quot;">​</a></h2><p>Use the bottom <code>Zoom</code> buttons to change the optical zoom immediately.</p><ul><li><code>1x</code>, <code>3x</code>, <code>8x</code>, <code>16x</code>, <code>32x</code>: fixed zoom selection</li><li><code>Center</code>: return the camera direction to the default center position</li></ul><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="PTZ zoom and switch control" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Zoom buttons and switch area</figcaption></figure><h2 id="_4-video-mode-joystick" tabindex="-1">4) Video mode &amp; joystick <a class="header-anchor" href="#_4-video-mode-joystick" aria-label="Permalink to &quot;4) Video mode &amp; joystick&quot;">​</a></h2><p>On the bottom-right, you can control the <strong>Thermal/Color</strong> switch and the virtual joystick display.</p><ul><li><strong>Thermal / Color</strong>: switch between thermal (<code>Thermal</code>) and color (<code>Color</code>) video</li><li><strong>Joystick icon</strong> (center of the right side of the screen): tap to show/hide the virtual joystick panel</li></ul><h2 id="_5-exit" tabindex="-1">5) Exit <a class="header-anchor" href="#_5-exit" aria-label="Permalink to &quot;5) Exit&quot;">​</a></h2><p>Press the <code>Exit</code> button at the top-right to close the PTZ screen and return to the basic GUI screen.</p><h2 id="demo-video" tabindex="-1">Demo video <a class="header-anchor" href="#demo-video" aria-label="Permalink to &quot;Demo video&quot;">​</a></h2>',17),e("figure",{style:{"text-align":"center",margin:"1rem 0"}},[e("iframe",{width:"640",height:"360",src:"https://www.youtube.com/embed/ThilVsiWMfc",title:"PTZ basic operation",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),e("figcaption",{style:{"text-align":"center","margin-top":"0.5rem",color:"var(--vp-c-text-2, #666)","font-size":"0.95em"}},"PTZ basic operation")],-1)])])}const _=i(c,[["render",s]]);export{y as __pageData,_ as default};
